-- Enable workspace profile editing through the existing user-JWT/RLS client.
-- No grants, service-role elevation, lifecycle changes, or tenant reassignment.
-- Source-only migration: apply only after isolated database validation and approval.

create or replace function guard_organization_profile_update()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, public
as $$
begin
  -- Use the actual database role, not caller-controlled request JWT settings.
  -- Existing SECURITY DEFINER maintenance functions execute as their owner and
  -- retain their current authority; this trigger does not grant that authority.
  if current_user in ('authenticated', 'anon') then
    if (to_jsonb(new) - array[
      'legal_name', 'display_name', 'tax_id', 'country_code', 'timezone', 'updated_at'
    ]) is distinct from (to_jsonb(old) - array[
      'legal_name', 'display_name', 'tax_id', 'country_code', 'timezone', 'updated_at'
    ]) then
      raise exception 'Only organization profile fields may be updated'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

-- PostgreSQL orders same-event triggers alphabetically. This guard runs before
-- trg_organizations_updated_at; updated_at is ignored so either order is safe.
drop trigger if exists trg_organizations_profile_fields_guard on organizations;
create trigger trg_organizations_profile_fields_guard
before update on organizations
for each row execute function guard_organization_profile_update();

-- SELECT continues to use the existing active-membership policy. UPDATE is
-- limited to owner/admin of the same old/new organization and writable plan.
drop policy if exists organizations_profile_update_policy on organizations;
create policy organizations_profile_update_policy
  on organizations for update to authenticated
  using (
    is_active_org_member(id, array['owner', 'admin']::member_role[])
    and organization_is_writable(id)
  )
  with check (
    is_active_org_member(id, array['owner', 'admin']::member_role[])
    and organization_is_writable(id)
  );

-- Keep project identity and tenant binding stable during user-JWT updates.
-- Existing profile/lifecycle policies, grants and maintenance authority are unchanged.
-- Apply only after isolated validation and the normal deployment approval.
create or replace function guard_project_identity_update()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, public
as $$
begin
  -- The database role is authoritative; caller-controlled JWT settings are not.
  if current_user in ('authenticated', 'anon')
     and (new.id is distinct from old.id
       or new.organization_id is distinct from old.organization_id) then
    raise exception 'Project identity and organization binding cannot be changed'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_projects_identity_guard on projects;
create trigger trg_projects_identity_guard
before update on projects
for each row execute function guard_project_identity_update();

-- These six internal write RPCs are invoked only by Edge service-role handlers.
-- Handlers check JWT/member access and separately enforce subscription policy.
-- SECURITY DEFINER bodies must not be callable by clients that bypass those checks.
-- Revoke direct client execution; leave frontend member/create-org RPCs unchanged.
-- Source migration only: deployment still requires the normal approval boundary.
begin;

revoke all on function confirm_draft_atomic(uuid, uuid, uuid, text, draft_status, text, timestamptz, jsonb, jsonb, uuid, text)
  from public, anon, authenticated;
grant execute on function confirm_draft_atomic(uuid, uuid, uuid, text, draft_status, text, timestamptz, jsonb, jsonb, uuid, text)
  to service_role;

revoke all on function process_document_atomic(uuid, uuid, uuid, jsonb, jsonb, draft_status, numeric, text, text, text)
  from public, anon, authenticated;
grant execute on function process_document_atomic(uuid, uuid, uuid, jsonb, jsonb, draft_status, numeric, text, text, text)
  to service_role;

revoke all on function recalculate_project_atomic(uuid, uuid, uuid, jsonb, text)
  from public, anon, authenticated;
grant execute on function recalculate_project_atomic(uuid, uuid, uuid, jsonb, text)
  to service_role;

revoke all on function generate_report_atomic(uuid, uuid, uuid, integer, jsonb, text, date, date, integer, integer, integer, jsonb, jsonb, jsonb, integer, timestamptz, text)
  from public, anon, authenticated;
grant execute on function generate_report_atomic(uuid, uuid, uuid, integer, jsonb, text, date, date, integer, integer, integer, jsonb, jsonb, jsonb, integer, timestamptz, text)
  to service_role;

revoke all on function run_ai_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, numeric, text)
  from public, anon, authenticated;
grant execute on function run_ai_audit_atomic(uuid, uuid, uuid, uuid, text, text, text, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, numeric, text)
  to service_role;

revoke all on function classify_document_atomic(uuid, uuid, uuid, classification_status, text, smallint, numeric, text, text, text, text)
  from public, anon, authenticated;
grant execute on function classify_document_atomic(uuid, uuid, uuid, classification_status, text, smallint, numeric, text, text, text, text)
  to service_role;

commit;

